import os, pty, sys, time, fcntl, termios, struct, select, subprocess, signal

EXE = os.environ.get('EXE', '/workspace/executable')

def run(args=(), cols=80, rows=24, json_in=None, keys=(), wait=0.45,
        key_delay=0.18, stdout_tty=False, env=None, exe=None, final_wait=0.4):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    e = dict(os.environ); e.setdefault('TERM','xterm-256color')
    e.pop('COLUMNS',None); e.pop('LINES',None)
    if env: e.update(env)
    outr, outw = os.pipe()
    inr = inw = None
    if json_in is not None:
        inr, inw = os.pipe()
    def setup():
        os.setsid(); fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
    cmd = [exe or EXE] + [str(x) for x in args]
    p = subprocess.Popen(cmd, stdin=(inr if inr is not None else slave),
                         stdout=(slave if stdout_tty else outw),
                         stderr=(slave if stdout_tty else outw),
                         env=e, close_fds=True, preexec_fn=setup)
    os.close(slave); os.close(outw)
    if inr is not None:
        os.close(inr); os.write(inw, json_in); os.close(inw)
    buf = bytearray(); tbuf = bytearray()
    def pump(t):
        end = time.time()+t
        while time.time() < end:
            try:
                r,_,_ = select.select([master, outr], [], [], 0.02)
            except Exception:
                return
            for f in r:
                try: d = os.read(f, 1<<16)
                except OSError: d = b''
                (tbuf if f == master else buf).extend(d)
    pump(wait)
