STR={17:[2,6,2,7],16:[2,6,2,6],15:[2,6,2,5],14:[2,6,2,4],13:[2,6,2,3],12:[2,6,2,2],
     11:[2,6,2,1],10:[2,6,2,0],9:[2,6,1,0],8:[2,5,1,0],7:[2,4,1,0],6:[2,3,1,0],5:[1,3,1,0],4:[1,3,0,0]}

def hard(mins, fs, extra, size, order):
    out=[0]*len(mins)
    for i in order:
        if fs[i]: out[i]=0; continue
        add=extra*mins[i]//max(1,size)
        extra-=add; size-=mins[i]; out[i]=mins[i]-add
    return out
def easy(mins, fs, extra, ssum, order):
    out=[0]*len(mins)
    for i in order:
        add=extra*mins[i]*fs[i]//max(1,ssum)
        extra-=add; ssum-=mins[i]*fs[i]; out[i]=mins[i]-add
    return out
def compute(mins, fs, target, order):
    size=sum(mins)
    if size<=target:
        return list(mins)
    extra=size-target
    fss=sum(m for m,f in zip(mins,fs) if f)
    fsum=sum(m*f for m,f in zip(mins,fs))
    if fss>=extra:
        return easy(mins,fs,extra,fsum,order)
    return hard(mins,fs,extra-fss,size-fss,order)

def try_all(table, mins, maxfs=3):
    n=len(mins); found=[]
    for order in itertools.permutations(range(n)):
        for fs in itertools.product(range(maxfs+1),repeat=n):
            ok=True
            for t,exp in table.items():
                if compute(mins,fs,t,order)!=exp: ok=False;break
            if ok: found.append((order,fs))
    return found
